import React from 'react';
import './i18n/config';
import MainLayout from './page/Main';
import Box from '@mui/material/Box';
import AppRoutes from './layouts/AppRoutes';
import withAppProviders from './withAppProviders';
import LoginProvider from './page/Auth/LoginProvider';
import { BrowserRouter } from 'react-router-dom';
import { BASENAME } from './config';
import MiniDrawer from './layouts/Menu/Drawer';
import { useIdleLogout } from './core/hooks/useIdleLogout';
import IdleTimeoutPopup from './components/ModelPopup/IdleTimeoutPopup';

if (process.env.NODE_ENV === 'development') {
  require('./mocks/browser');
  //  worker.start();
}

const App = () => {
  const { showPopup, stay, logout } = useIdleLogout();

  return (
    <Box data-testid="pos-ui-app">
      <MainLayout>
        <BrowserRouter basename={BASENAME}>
          <LoginProvider>
            <Box>
              <MiniDrawer>
                <AppRoutes />
              </MiniDrawer>
              <IdleTimeoutPopup
                onLogout={logout}
                onStay={stay}
                open={showPopup}
              />
            </Box>
          </LoginProvider>
        </BrowserRouter>
      </MainLayout>
    </Box>
  );
};

export default withAppProviders(App)();
