import React from 'react';
import {
  Box,
  Collapse,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
  Tooltip,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { menuList } from '../menuList';
import { MenuItem } from '../types';
import { TEAL } from '../constants';

interface DrawerMenuListProps {
  open: boolean;
  isSmall: boolean;
  expandMenu: string;
  currentMenuName: string;
  userHasRight: (privilege: string) => boolean;
  navigate: (path: string) => void;
  setOpen: (open: boolean) => void;
  onMainItemClick: (ml: MenuItem) => void;
}


/** Colored icon box for dark sidebar */
const IconBox: React.FC<{
  color: string;
  active: boolean;
  size?: number;
  radius?: number;
  children: React.ReactNode;
}> = ({ color, active, size = 26, radius = 6, children }) => (
  <Box
    sx={{
      alignItems: 'center',
      background: active ? alpha(color, 0.28) : alpha(color, 0.14),
      borderRadius: `${radius}px`,
      color: active ? color : alpha(color, 0.75),
      display: 'flex',
      flexShrink: 0,
      height: size,
      justifyContent: 'center',
      transition: 'all 0.15s',
      width: size,
    }}
  >
    {children}
  </Box>
);

const DrawerMenuList: React.FC<DrawerMenuListProps> = ({
  open,
  isSmall,
  expandMenu,
  currentMenuName,
  userHasRight,
  navigate,
  setOpen,
  onMainItemClick,
}) => (
  <List sx={{ pl: 0, pt: 0.5 }}>
    {menuList.map((ml) => {
      const shouldRender =
        (!ml.privilege || userHasRight(ml.privilege)) &&
        (!ml.submenus ||
          ml.submenus.some(
            (s) => !s.privilege || userHasRight(s.privilege)
          ));

      if (!shouldRender) return null;

      const isMainActive = currentMenuName === ml.path;
      const accent = ml.color ?? TEAL;
      const isExpanded = expandMenu === ml.title;

      return (
        <div key={ml.title}>
          <ListItem disablePadding>
            <Tooltip
              arrow
              placement="right-start"
              title={!open ? ml.title : ''}
            >
              <ListItemButton
                onClick={() => onMainItemClick(ml)}
                sx={{
                  alignItems: 'center',
                  borderRadius: 1.5,
                  display: 'flex',
                  gap: open ? 1.25 : 0,
                  justifyContent: open ? 'flex-start' : 'center',
                  margin: '1px 8px',
                  minHeight: 40,
                  position: 'relative',
                  px: open ? 1.25 : 0,
                  py: 0.5,
                  transition: 'background 0.15s',
                  ...(isMainActive && {
                    background: alpha(TEAL, 0.16),
                    '&::before': {
                      background: TEAL,
                      borderRadius: '0 3px 3px 0',
                      bottom: 6,
                      content: '""',
                      left: -8,
                      position: 'absolute',
                      top: 6,
                      width: 3,
                    },
                  }),
                  '&:hover': {
                    background: isMainActive
                      ? alpha(TEAL, 0.18)
                      : alpha('#fff', 0.06),
                  },
                }}
              >
                <IconBox active={isMainActive} color={accent} size={26}>
                  {ml.icon}
                </IconBox>

                {open && (
                  <ListItemText
                    primary={ml.title}
                    primaryTypographyProps={{
                      color: isMainActive ? '#fff' : alpha('#fff', 0.72),
                      fontSize: '13px',
                      fontWeight: isMainActive ? 700 : 500,
                    }}
                    sx={{ opacity: 1 }}
                  />
                )}

                {ml.submenus && open && (
                  <ExpandMoreIcon
                    sx={{
                      color: alpha('#fff', 0.3),
                      fontSize: 16,
                      ml: 'auto',
                      transform: isExpanded
                        ? 'rotate(180deg)'
                        : 'rotate(0deg)',
                      transition: 'transform 0.2s',
                    }}
                  />
                )}
              </ListItemButton>
            </Tooltip>
          </ListItem>

          {ml.submenus && (
            <Collapse in={isExpanded} timeout="auto" unmountOnExit>
              <List disablePadding sx={{ pb: 0.5 }}>
                {ml.submenus.map((submenu) => {
                  if (!(!submenu.privilege || userHasRight(submenu.privilege)))
                    return null;
                  const isSubActive = currentMenuName === submenu.path;

                  return (
                    <ListItem disablePadding key={submenu.title}>
                      <Tooltip
                        arrow
                        placement="right-start"
                        title={!open ? submenu.title : ''}
                      >
                        <ListItemButton
                          onClick={() => {
                            if (isSmall) setOpen(false);
                            if (submenu.newPage) {
                              window.open(submenu.path, '_blank');
                            } else if (currentMenuName !== submenu.path) {
                              navigate(submenu.path);
                            }
                          }}
                          sx={{
                            alignItems: 'center',
                            borderRadius: 1.5,
                            display: 'flex',
                            gap: open ? 1.25 : 0,
                            justifyContent: open ? 'flex-start' : 'center',
                            margin: '1px 8px',
                            minHeight: 34,
                            pl: open ? 1.25 : 0,
                            position: 'relative',
                            pr: 1.5,
                            py: 0.35,
                            transition: 'background 0.15s',
                            ...(isSubActive && {
                              background: alpha(TEAL, 0.16),
                              '&::before': {
                                background: TEAL,
                                borderRadius: '0 3px 3px 0',
                                bottom: 4,
                                content: '""',
                                left: -8,
                                position: 'absolute',
                                top: 4,
                                width: 3,
                              },
                            }),
                            '&:hover': {
                              background: isSubActive
                                ? alpha(TEAL, 0.18)
                                : alpha('#fff', 0.06),
                            },
                          }}
                        >
                          {open && (
                            <Box
                              sx={{
                                borderLeft: `2px solid ${alpha(accent, 0.25)}`,
                                flexShrink: 0,
                                height: 14,
                                ml: 1.5,
                                mr: 0.75,
                              }}
                            />
                          )}

                          <IconBox
                            active={isSubActive}
                            color={accent}
                            radius={6}
                            size={22}
                          >
                            {submenu.icon as React.ReactNode}
                          </IconBox>

                          {open && (
                            <Typography
                              sx={{
                                color: isSubActive
                                  ? '#fff'
                                  : alpha('#fff', 0.6),
                                fontSize: '12px',
                                fontWeight: isSubActive ? 600 : 400,
                                ml: 0.5,
                              }}
                            >
                              {submenu.title}
                            </Typography>
                          )}
                        </ListItemButton>
                      </Tooltip>
                    </ListItem>
                  );
                })}
              </List>
            </Collapse>
          )}
        </div>
      );
    })}
  </List>
);

export default DrawerMenuList;
