import React from 'react';
import { IOrderRecordsList } from '../../core/Interface/order.interface';
import { ColumnDef } from '@tanstack/react-table';
import { formatDateTime, getPriceFormat } from '../../core/utils';
import { Box } from '@mui/material';
import { useTranslation } from 'react-i18next';
import { appColors } from '../../theme/appColors';

const useSalesDetailsColumn = ({
  currencyCode,
}: {
  viewSaleDetails?: (id: string) => void;
  viewSaleDetailsPopUp?: (id: string) => void;
  currencyCode: string;
}) => {
  const { t } = useTranslation(['salesdetails']);

  return [
    {
      id: 'sn',
      header: '#',
      size: 50,
      cell: (cell) => {
        const { row, table } = cell;
        const { pageIndex, pageSize } = table.getState().pagination;

        return (
          <Box sx={{ textAlign: 'justify' }}>
            {pageIndex * pageSize + row.index + 1}
          </Box>
        );
      },
    },
    {
      accessorKey: 'orderNo',
      header: t('salesdetails:orderId'),
      size: 120,
    },
    {
      accessorKey: 'customerName.name',
      header: t('salesdetails:customerName'),
      size: 180,
    },
    {
      accessorKey: 'status',
      header: () => (
        <Box sx={{ textAlign: 'center' }}>{t('salesdetails:status')}</Box>
      ),
      size: 120,
      cell: (cell) => {
        const status = cell.row.original.status?.toLowerCase();
        const isCompleted = status === 'completed';

        return (
          <Box sx={{ textAlign: 'center' }}>
            <Box
              sx={{
                display: 'inline-block',
                px: 2,
                py: 0.75,
                borderRadius: 2,
                fontWeight: 600,
                fontSize: 13,
                backgroundColor: isCompleted
                  ? appColors.forestGreen[5]
                  : appColors.amberYellow[20],
                color: isCompleted
                  ? appColors.forestGreen[100]
                  : appColors.amberYellow[100],
              }}
            >
              {cell.row.original.status}
            </Box>
          </Box>
        );
      },
    },
    {
      accessorKey: 'received',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>{t('salesdetails:advance')}</Box>
      ),
      size: 180,
      cell: (cell) => (
        <Box sx={{ textAlign: 'right' }}>
          {getPriceFormat(cell.row.original.received, currencyCode)}
        </Box>
      ),
    },
    {
      accessorKey: 'dateTime',
      size: 200,
      header: () => (
        <Box sx={{ textAlign: 'right' }}>{t('salesdetails:date')}</Box>
      ),
      cell: (cell) => (
        <Box sx={{ textAlign: 'right', height: 30 }}>
          {formatDateTime(new Date(cell.row.original.dateTime))}
        </Box>
      ),
    },
    {
      accessorKey: 'deliveryDateTime',
      size: 200,
      header: () => <Box sx={{ textAlign: 'right' }}>Delivery Date</Box>,
      cell: (cell) => (
        <Box sx={{ textAlign: 'right', height: 30 }}>
          {formatDateTime(new Date(cell.row.original.deliveryDateTime))}
        </Box>
      ),
    },
    {
      accessorKey: 'id',
    },
  ] as ColumnDef<IOrderRecordsList>[];
};

export default useSalesDetailsColumn;
