import moment from 'moment';
import { CURRENCY } from '../config';
import { useMediaQuery, useTheme } from '@mui/material';

const priceFormatter = new Intl.NumberFormat('en-US', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

const toNumericAmount = (amount: number | string): number =>
  typeof amount === 'string' ? Number(amount.replace(/,/g, '')) : amount;

export const downloadPdf = (url: string) => {
  window.open(url, '_blank');
};

export const useIsSmallScreen = () => {
  const theme = useTheme();
  return useMediaQuery(theme.breakpoints.down('sm'));
};

export const useIsMediumScreen = () => {
  const theme = useTheme();
  return useMediaQuery(theme.breakpoints.down('md'));
};

export const getPriceFormatCodeToSymbol = (
  amount: number | string,
  currency?: string
): string => {
  const formatter = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: CURRENCY,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  return formatter.format(toNumericAmount(amount));
};

type FontSizeResult = {
  fontSize: number;
  label: string;
  fontWeight?: string;
};

export const calculateFontSize = (width: number): FontSizeResult => {
  if (width === 217) return { fontSize: 10, label: '58mm' };
  if (width === 300) return { fontSize: 12, label: '80mm', fontWeight: 'bold' };
  if (width === 557) return { fontSize: 14, label: 'A5' };
  if (width === 790) return { fontSize: 16, label: 'A4' };
  return { fontSize: 12, label: 'Default' };
};

export const getPriceFormat = (
  amount: number | string,
  currency?: string
): string => {
  const formattedAmount = priceFormatter.format(toNumericAmount(amount));

  if (currency) {
    return `${currency.toUpperCase()} ${formattedAmount}`;
  }

  return formattedAmount;
};

export const getPriceFormatWithoutCurrency = (
  amount: number | string
): string => {
  return priceFormatter.format(toNumericAmount(amount));
};

export const getPriceFormatWithCurrencyCode = (
  amount: number | string,
  curr_code: string
): string => {
  const amountFormat = getPriceFormatWithoutCurrency(amount);
  const formatter = `${curr_code} ${amountFormat}`;
  return formatter;
};

export const getMetricValueFormat = (
  label: string,
  value: number | string
): string => {
  const text = String(value);
  const isCount = /count|quantity|qty|stock|points|records?/i.test(label)
    || /users|branches|percent|%/i.test(label);
  if (isCount) {
    return typeof value === 'number' ? value.toLocaleString('en-US') : text;
  }

  const currencyValue = text.match(
    /^(\s*(?:[A-Z]{3}|Rs\.?|[$€£₹])\s*)(-?[\d,]+(?:\.\d+)?)\s*$/i
  );
  if (currencyValue) {
    return `${currencyValue[1]}${getPriceFormatWithoutCurrency(currencyValue[2])}`;
  }

  const isAmount = /amount|price|total|balance|received|advance/i.test(label)
    || /charge|fee|credit|cost|discount|paid|earning/i.test(label)
    || /revenue|income|profit|sale|purchase|payment|cash|return/i.test(label);
  if (isAmount && Number.isFinite(toNumericAmount(value))) {
    return getPriceFormatWithoutCurrency(value);
  }
  return typeof value === 'number' ? value.toLocaleString('en-US') : text;
};

export const formatDate = (date: Date): string => {
  return moment(date).format('DD-MM-YYYY');
};

export const formatDateTime = (date: Date): string => {
  return moment(date).format('DD-MM-YYYY hh:mm A');
};

export const formatDateMonthYear = (date: Date): string => {
  return moment(date).format('MMMM YYYY');
};

export const formatTimeToUtc = (date: string) => {
  if (!date.includes('Z')) {
    date = date + 'Z';
  }
  return moment(date).format('DD-MM-YYYY hh:mm A');
};

export const formatUtcToTime = (date: string) => {
  if (!date.includes('Z')) {
    date = date + 'Z';
  }
  return moment(date).utcOffset('+05:30').format('DD-MM-YYYY hh:mm A');
};

const characters =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

export const generateString = (length: number) => {
  let result = '';
  const charactersLength = characters.length;
  for (let i = 0; i < length; i++) {
    result += characters.charAt(Math.floor(Math.random() * charactersLength));
  }
  return result;
};

export const uploadImage = async (file: File): Promise<string | null> => {
  try {
    const formData = new FormData();
    formData.append('file', file);

    const response = await fetch(
      'https://allesfiles.azurewebsites.net/api/upload',
      {
        method: 'POST',
        body: formData,
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token') || ''}`,
        },
      }
    );

    if (!response.ok) {
      throw new Error(`Upload failed: ${response.statusText}`);
    }

    const responseData = await response.json();

    // Ensure filePath is properly stored
    return responseData.filePath || null;
  } catch (error) {
    console.error('Error uploading image:', error);
    throw error;
  }
};


export function isEffectivelyEmpty(arr: unknown): boolean {
  if (!Array.isArray(arr)) return true;

  return arr.every(v => (v ?? "").toString().trim() === "");
}
