import React, { useState } from 'react';
import { TextField, TextFieldProps } from '@mui/material';
import { getPriceFormatWithoutCurrency } from '../../core/utils';

type MoneyFieldProps = TextFieldProps & {
  formatAmount?: boolean;
};

const MoneyField = React.forwardRef<HTMLDivElement, MoneyFieldProps>(({
  formatAmount = true,
  onBlur,
  onFocus,
  value,
  ...props
}, ref) => {
  const [isFocused, setIsFocused] = useState(false);
  const isNumeric = (typeof value === 'number' || typeof value === 'string')
    && String(value).trim() !== ''
    && Number.isFinite(Number(String(value).replace(/,/g, '')));
  const displayValue = formatAmount && !isFocused && isNumeric
    ? getPriceFormatWithoutCurrency(value as number | string).replace(/,/g, '')
    : value;

  return (
    <TextField
      {...props}
      onBlur={(event) => {
        setIsFocused(false);
        onBlur?.(event);
      }}
      onFocus={(event) => {
        setIsFocused(true);
        onFocus?.(event);
      }}
      ref={ref}
      value={displayValue}
    />
  );
});

MoneyField.displayName = 'MoneyField';

export default React.memo(MoneyField);
